/// Encounter matrix data for Tales of the Arabian Nights.
///
/// The encounter matrix maps (encounterIndex, dieRoll) to a letter (A-O)
/// and a name string. Encounter indices are 0-based (0-120), die rolls
/// are 0-based (0-11). Some indices are excluded from the game.
class EncounterData {
  EncounterData._();

  static const Set<int> _excludedGameNumbers = {89, 96, 103, 104, 111, 112};

  /// Returns true if the 1-based encounter number (1-121) exists in the game.
  static bool isValidEncounter(int encounterNum) {
    if (encounterNum < 1 || encounterNum > 121) return false;
    return !_excludedGameNumbers.contains(encounterNum);
  }

  /// Returns the matrix letter for a 0-based encounter index and die roll.
  static String getMatrix(int encounter, int roll) {
    final row = _matrix[encounter];
    if (row == null || roll < 0 || roll >= row.length) return '';
    return row[roll];
  }

  /// Returns the encounter name for a 0-based encounter index and die roll.
  static String getName(int encounter, int roll) {
    final row = _names[encounter];
    if (row == null || roll < 0 || roll >= row.length) return '';
    return row[roll];
  }

